<?php
require __DIR__.'/includes/bootstrap.php';require_permission('notifications.view');$q=db()->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100');$q->execute([current_user_id()]);$notifications=$q->fetchAll();$title='Notifications';$active='notifications';include __DIR__.'/includes/header.php';?>
<section class="section-toolbar reveal"><div><p class="eyebrow">Attention center</p><h2>Notifications</h2><p class="muted">Assignments, deadlines, overdue alerts, and campaign events.</p></div></section><section class="panel reveal stagger-1"><div class="notification-list"><?php if(!$notifications):?><div class="empty-state"><i data-lucide="bell-off"></i><h4>All quiet</h4><p>No notifications have been generated for your account.</p></div><?php else:foreach($notifications as $n):?><article class="notification-row <?=$n['read_at']?'':'unread'?>"><span class="notification-icon"><i data-lucide="bell-ring"></i></span><div><strong><?=e($n['title'])?></strong><p><?=e($n['message'])?></p><small><?=e(format_datetime($n['created_at']))?></small></div><div><?php if(!$n['read_at']):?><form method="post" action="<?=e(url('handlers/notification-read.php'))?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$n['id']?>"><button class="btn btn-xs btn-soft">Mark read</button></form><?php else:?><span class="verified-mark"><i data-lucide="check"></i>Read</span><?php endif;?></div></article><?php endforeach;endif;?></div></section>
<?php include __DIR__.'/includes/footer.php';?>
